diff --git a/src/TaxDataMigrationHelper.Codeunit.al b/src/TaxDataMigrationHelper.Codeunit.al
new file mode 100644
--- /dev/null
+++ b/src/TaxDataMigrationHelper.Codeunit.al
@@ -0,0 +1,31 @@
+codeunit 50116 "Tax Data Migration Helper"
+{
+  Access = Internal;
+
+  var
+    ProgressTxt: Label 'Tax data migration progress: %1 of %2 records processed', Locked = true;
+
+  procedure MigrateTaxInformation(var VendorRecord: Record Vendor; SourceTaxId: Text[50])
+  begin
+    if SourceTaxId <> '' then begin
+      VendorRecord.Validate("Federal ID No.", FormatTaxId(SourceTaxId));
+      VendorRecord.Modify(true);
+    end;
+  end;
+
+  procedure ValidateTaxDataIntegrity(ExpectedTaxId: Text[50]; ActualTaxId: Text[50]): Boolean
+  begin
+    exit(ExpectedTaxId = ActualTaxId);
+  end;
+
+  local procedure FormatTaxId(RawTaxId: Text[50]): Text[50]
+  begin
+    exit(DelChr(RawTaxId, '=', '-()., '));
+  end;
+
+  procedure LogMigrationProgress(TotalRecords: Integer; ProcessedRecords: Integer)
+  begin
+    Session.LogMessage('TaxMigration', StrSubstNo(ProgressTxt, ProcessedRecords, TotalRecords),
+      Verbosity::Information, DataClassification::SystemMetadata, TelemetryScope::ExtensionPublisher);
+  end;
+}
