diff --git a/src/CleanFormatting.Codeunit.al b/src/CleanFormatting.Codeunit.al
new file mode 100644
--- /dev/null
+++ b/src/CleanFormatting.Codeunit.al
@@ -0,0 +1,35 @@
+codeunit 50004 "Clean Formatting"
+{
+    /// <summary>
+    /// Applies a discount percentage to a sales line.
+    /// </summary>
+    /// <param name="SalesLine">The sales line to update.</param>
+    /// <param name="DiscountPct">The discount percentage to apply.</param>
+    procedure ApplyDiscount(var SalesLine: Record "Sales Line"; DiscountPct: Decimal)
+    begin
+        if DiscountPct <= 0 then
+            exit;
+
+        if DiscountPct > 100 then
+            DiscountPct := 100;
+
+        SalesLine."Line Discount %" := DiscountPct;
+        SalesLine.Modify(true);
+    end;
+
+    /// <summary>
+    /// Finds the unit price for an item.
+    /// </summary>
+    /// <param name="ItemNo">The item number to look up.</param>
+    /// <returns>The unit price of the item.</returns>
+    procedure FindUnitPrice(ItemNo: Code[20]): Decimal
+    var
+        Item: Record Item;
+    begin
+        Item.SetLoadFields("Unit Price");
+        if Item.Get(ItemNo) then
+            exit(Item."Unit Price");
+
+        exit(0);
+    end;
+}
