diff --git a/src/SampleQltyGenRule.Table.al b/src/SampleQltyGenRule.Table.al
new file mode 100644
index 00000000..45dd6868
--- /dev/null
+++ b/src/SampleQltyGenRule.Table.al
@@ -0,0 +1,64 @@
+table 50130 "Sample Qlty Gen Rule"
+{
+    DataClassification = CustomerContent;
+
+    fields
+    {
+        field(1; "Entry No."; Integer)
+        {
+            Caption = 'Entry No.';
+        }
+        field(2; "Source Table No."; Integer)
+        {
+            Caption = 'Table No.';
+            NotBlank = true;
+            TableRelation = AllObjWithCaption."Object ID" where("Object Type" = const(Table));
+            ToolTip = 'Specifies the table for this rule.';
+        }
+        field(3; "Table Caption"; Text[250])
+        {
+            CalcFormula = lookup(AllObjWithCaption."Object Caption" where("Object Type" = const(Table),
+                                                                          "Object ID" = field("Source Table No.")));
+            Caption = 'Table';
+            Editable = false;
+            FieldClass = FlowField;
+            ToolTip = 'Specifies the table for this rule.';
+        }
+    }
+
+    keys
+    {
+        key(PK; "Entry No.")
+        {
+            Clustered = true;
+        }
+    }
+
+    trigger OnInsert()
+    begin
+        CheckSourceTableNoIsSet();
+    end;
+
+    trigger OnModify()
+    begin
+        CheckSourceTableNoIsSet();
+    end;
+
+    var
+        TableMissingErr: Label 'You must select a table before saving.';
+
+    local procedure CheckSourceTableNoIsSet()
+    begin
+        if Rec."Source Table No." = 0 then
+            Error(TableMissingErr);
+    end;
+
+    procedure HandleOnAssistEditSourceTable()
+    var
+        AllObjWithCaption: Record AllObjWithCaption;
+    begin
+        AllObjWithCaption.SetRange("Object Type", AllObjWithCaption."Object Type"::Table);
+        if Page.RunModal(Page::"Objects", AllObjWithCaption) = Action::LookupOK then
+            Rec.Validate("Source Table No.", AllObjWithCaption."Object ID");
+    end;
+}
